      out.write("    tbS.innerHTML = '<tr><td colspan=\"2\" style=\"text-align:center; padding:24px; color:var(--color-text-muted);\">Đang tải đặc tính kỹ thuật...</td></tr>';\n");
      out.write("    \n");
      out.write("    fetch('");
