      out.write("                    var bcHtml = v.barcode \n");
      out.write("                        ? '<div class=\"barcode-display-box\" style=\"display:inline-flex;align-items:center;gap:8px;background:var(--color-surface);padding:4px 8px;border-radius:4px;border:1px solid var(--color-border)\"><div id=\"'+qrId+'\" style=\"flex-shrink:0;background:#fff;padding:2px;border:1px solid var(--color-border);border-radius:3px\"></div><div><svg id=\"'+bcId+'\" style=\"max-width:110px;height:32px\"></svg><br><small style=\"color:var(--color-text);font-size:11px;font-weight:700;font-family:monospace\">'+v.barcode+'</small></div></div>'\n");
      out.write("                        : '<span style=\"color:var(--color-text-muted); font-size:12px;\">Chưa có mã vạch</span>';\n");
      out.write("                    var stockBadge = v.soLuong > 0 ? '<span class=\"badge badge-success font-mono\">Còn: ' + v.soLuong + '</span>' : '<span class=\"badge badge-danger font-mono\">Hết hàng</span>';\n");
      out.write("                    return '<tr>'\n");
      out.write("                        + '<td style=\"font-weight:700; text-align:center;\" class=\"font-mono\">' + (i+1) + '</td>'\n");
      out.write("                        + '<td style=\"font-weight:600;\">' + (v.mauSac || '-') + '</td>'\n");
      out.write("                        + '<td style=\"font-weight:600;\">' + (v.trongLuong || '-') + '</td>'\n");
      out.write("                        + '<td class=\"money font-mono\" style=\"font-weight:700;\">' + Number(v.giaBan).toLocaleString('vi-VN') + ' đ</td>'\n");
      out.write("                        + '<td style=\"text-align:center;\">' + stockBadge + '</td>'\n");
