      out.write("            tbS.innerHTML = '<tr><td colspan=\"2\" style=\"text-align:center; padding:20px; color:var(--color-danger);\">Lỗi tải kết nối dữ liệu. Vui lòng thử lại!</td></tr>'; \n");
      out.write("        });\n");
      out.write("}\n");
      out.write("</script>\n");
