      out.write("        '</div><button type=\"button\" class=\"btn btn-outline\" onclick=\"clearCustomer()\" style=\"font-size:11px;padding:2px 8px;color:var(--color-danger);border-color:var(--color-danger);\">Bỏ chọn</button></div>';\n");
