      out.write("function addProductFromButton(btn) {\n");
      out.write("    var id = btn.getAttribute('data-id');\n");
      out.write("    var mauEl = document.getElementById('mau_'+id);\n");
      out.write("    var tlEl = document.getElementById('tl_'+id);\n");
      out.write("    var tonKho = parseInt(btn.getAttribute('data-stock')||'0', 10);\n");
      out.write("    var jsonEl = document.getElementById('vjson_' + id);\n");
      out.write("    if (jsonEl) {\n");
      out.write("        try {\n");
      out.write("            var variants = JSON.parse(jsonEl.textContent || '[]');\n");
      out.write("            var selMau = mauEl ? mauEl.value.trim() : '';\n");
      out.write("            var selTl = tlEl ? tlEl.value.trim() : '';\n");
      out.write("            var found = variants.find(function(v) { return v.mau === selMau && v.tl === selTl; });\n");
      out.write("            if (!found && variants.length > 0) found = variants.find(function(v) { return v.mau === selMau; }) || variants[0];\n");
      out.write("            if (found && found.sl !== undefined) tonKho = found.sl;\n");
      out.write("        } catch(e) {}\n");
      out.write("    }\n");
      out.write("    return addToCart(id, btn.getAttribute('data-masp'), btn.getAttribute('data-name'),\n");
      out.write("              btn.getAttribute('data-price'), tonKho,\n");
      out.write("              mauEl?mauEl.value:'', tlEl?tlEl.value:'');\n");
      out.write("}\n");
      out.write("\n");
      out.write("function addToCart(id, maSP, tenSP, gia, tonKho, mauSac, trongLuong) {\n");
      out.write("    var qtyInput = document.getElementById('qty_'+id);\n");
      out.write("    var parsedQty = parseInt(qtyInput.value, 10);\n");
      out.write("    if (isNaN(parsedQty) || parsedQty <= 0) {\n");
      out.write("        alert('Số lượng thêm vào không hợp lệ (phải > 0)!');\n");
      out.write("        if(qtyInput) qtyInput.value = 1;\n");
      out.write("        return false;\n");
      out.write("    }\n");
      out.write("    var qty = parsedQty;\n");
      out.write("    tonKho = Number(tonKho);\n");
      out.write("    var existing = cart.find(function(i){return i.id == id && (i.mauSac||'') === (mauSac||'') && (i.trongLuong||'') === (trongLuong||'')});\n");
      out.write("    var currentQty = existing ? existing.qty : 0;\n");
      out.write("    if (currentQty + qty > tonKho) { alert('Vượt số lượng tồn kho (' + tonKho + ')!'); return false; }\n");
      out.write("    if (existing) existing.qty += qty;\n");
      out.write("    else cart.push({id:id, maSP:maSP||'SP', tenSP:tenSP, gia:Number(gia), tonKho:tonKho, qty:qty, mauSac:mauSac||'', trongLuong:trongLuong||''});\n");
      out.write("    if(qtyInput) qtyInput.value = 1;\n");
      out.write("    renderCart();\n");
      out.write("    return true;\n");
