      out.write("                '<td style=\"text-align:center;\"><div style=\"display:inline-flex;align-items:center;gap:4px;background:var(--color-bg-subtle);border:1px solid var(--color-border);border-radius:4px;padding:2px 4px;\"><button type=\"button\" class=\"btn btn-outline\" style=\"width:24px;height:24px;padding:0;font-weight:700;\" onclick=\"changeQty('+i+',-1)\">-</button><strong class=\"font-mono\" style=\"min-width:24px;text-align:center;font-size:13.5px;\">'+item.qty+'</strong><button type=\"button\" class=\"btn btn-outline\" style=\"width:24px;height:24px;padding:0;font-weight:700;\" onclick=\"changeQty('+i+',1)\">+</button></div></td>' +\n");
