      out.write("function handlePosBarcodeInput(event) {\n");
      out.write("    if (event.key === 'Enter' || event.keyCode === 13) {\n");
      out.write("        event.preventDefault();\n");
      out.write("        var val = (event.target.value || '').trim().toUpperCase();\n");
      out.write("        if (!val) return;\n");
      out.write("        \n");
      out.write("        var statusEl = document.getElementById('posInputStatus');\n");
      out.write("        if (statusEl) {\n");
      out.write("            statusEl.style.display = 'block';\n");
      out.write("            statusEl.className = 'alert alert-info';\n");
      out.write("            statusEl.textContent = 'Đang kiểm tra mã vạch: ' + val + '...';\n");
      out.write("        }\n");
      out.write("        \n");
      out.write("        fetch(scannerContextPath + '/OrderServlet?ajaxScanBarcode=1&barcode=' + encodeURIComponent(val))\n");
      out.write("            .then(function(r) { return r.json(); })\n");
      out.write("            .then(function(data) {\n");
      out.write("                if (data.found) {\n");
      out.write("                    addToCartByBarcode(data);\n");
      out.write("                    playBeep();\n");
      out.write("                    showFeedbackToast('Đã thêm: ' + data.tenSP);\n");
      out.write("                    event.target.value = '';\n");
      out.write("                    if (statusEl) {\n");
      out.write("                        statusEl.className = 'alert alert-success';\n");
      out.write("                        statusEl.textContent = 'Đã thêm: ' + data.tenSP;\n");
      out.write("                        setTimeout(function() { statusEl.style.display = 'none'; }, 2500);\n");
      out.write("                    }\n");
      out.write("                } else {\n");
      out.write("                    if (statusEl) {\n");
      out.write("                        statusEl.className = 'alert alert-danger';\n");
      out.write("                        statusEl.textContent = 'Không tìm thấy sản phẩm nào khớp với mã: ' + val;\n");
      out.write("                    }\n");
      out.write("                    playErrorBeep();\n");
      out.write("                }\n");
      out.write("            })\n");
      out.write("            .catch(function() {\n");
      out.write("                if (statusEl) {\n");
      out.write("                    statusEl.className = 'alert alert-danger';\n");
      out.write("                    statusEl.textContent = 'Lỗi kết nối đến máy chủ!';\n");
      out.write("                }\n");
      out.write("            });\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("function playErrorBeep() {\n");
      out.write("    try {\n");
      out.write("        var ctx = new (window.AudioContext || window.webkitAudioContext)();\n");
      out.write("        var o = ctx.createOscillator();\n");
      out.write("        var g = ctx.createGain();\n");
      out.write("        o.connect(g); g.connect(ctx.destination);\n");
      out.write("        o.frequency.value = 220;\n");
      out.write("        o.type = 'sawtooth';\n");
      out.write("        g.gain.setValueAtTime(0.4, ctx.currentTime);\n");
      out.write("        o.start(ctx.currentTime);\n");
      out.write("        o.stop(ctx.currentTime + 0.35);\n");
      out.write("    } catch(e) {}\n");
      out.write("}\n");
      out.write("\n");
      out.write("function handlePaidInput(el) {\n");
      out.write("    var raw = (el.value || '').replace(/[^0-9]/g, '');\n");
      out.write("    if (raw === '') {\n");
      out.write("        el.value = '';\n");
      out.write("    } else {\n");
      out.write("        raw = parseInt(raw, 10).toString();\n");
      out.write("        el.value = raw.replace(/\\B(?=(\\d{3})+(?!\\d))/g, \".\");\n");
      out.write("    }\n");
      out.write("    calculateTotals();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function calculateTotals() {\n");
      out.write("    var subtotal = cart.reduce(function(t,i){return t+i.gia*i.qty},0);\n");
      out.write("    if (!cart.length && appliedVoucherCode) {\n");
      out.write("        appliedVoucherCode = '';\n");
      out.write("        appliedVoucherAmount = 0;\n");
      out.write("        appliedVoucherMinOrder = 0;\n");
      out.write("        if(document.getElementById('voucherInput')) document.getElementById('voucherInput').value = '';\n");
      out.write("        var resEl = document.getElementById('voucherResult');\n");
      out.write("        if (resEl) { resEl.className = 'voucher-result'; resEl.textContent = ''; resEl.style.display = 'none'; }\n");
      out.write("        if (document.getElementById('btnCancelVoucher')) document.getElementById('btnCancelVoucher').style.display = 'none';\n");
      out.write("    } else if (appliedVoucherCode && appliedVoucherMinOrder > 0 && subtotal < appliedVoucherMinOrder) {\n");
      out.write("        appliedVoucherCode = '';\n");
      out.write("        appliedVoucherAmount = 0;\n");
      out.write("        var reqMin = appliedVoucherMinOrder;\n");
      out.write("        appliedVoucherMinOrder = 0;\n");
      out.write("        if(document.getElementById('voucherInput')) document.getElementById('voucherInput').value = '';\n");
      out.write("        var resEl = document.getElementById('voucherResult');\n");
      out.write("        if (resEl) {\n");
      out.write("            resEl.className = 'alert alert-warning';\n");
      out.write("            resEl.textContent = 'Đã tự động gỡ voucher do đơn hàng chưa đạt mức tối thiểu (' + money(reqMin) + ')!';\n");
      out.write("            resEl.style.display = 'block';\n");
      out.write("        }\n");
      out.write("        if (document.getElementById('btnCancelVoucher')) document.getElementById('btnCancelVoucher').style.display = 'none';\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    var disc = Math.round(subtotal * currentDiscountPct / 100);\n");
      out.write("    var voucherDisc = appliedVoucherAmount > 0 ? Math.min(appliedVoucherAmount, subtotal - disc) : 0;\n");
      out.write("    var taxableBase = Math.max(0, subtotal - disc - voucherDisc);\n");
      out.write("    var vat = Math.round(taxableBase * VAT_PCT / 100); \n");
      out.write("    var grand = taxableBase + vat;\n");
      out.write("\n");
      out.write("    var paidStr = (document.getElementById('customerPaidInput').value || '').replace(/[^0-9]/g, '');\n");
      out.write("    var paid = parseFloat(paidStr) || 0;\n");
      out.write("    if (paid < 0) paid = 0;\n");
      out.write("    var change = Math.max(0, paid - grand);\n");
      out.write("    document.getElementById('subtotalText').textContent = money(subtotal);\n");
      out.write("    document.getElementById('discountPctLabel').textContent = currentDiscountPct;\n");
      out.write("    document.getElementById('discountAmountText').textContent = '- ' + money(disc);\n");
      out.write("    document.getElementById('vatAmountText').textContent = '+ ' + money(vat);\n");
      out.write("    document.getElementById('grandTotalText').textContent = money(grand);\n");
      out.write("    document.getElementById('changeText').textContent = money(change);\n");
      out.write("    var warnEl = document.getElementById('paidWarn');\n");
      out.write("    warnEl.style.display = (paid > 0 && paid < grand) ? 'block' : 'none';\n");
      out.write("    document.getElementById('discountAmountPost').value = disc;\n");
      out.write("    document.getElementById('vatAmountPost').value = vat;\n");
      out.write("    document.getElementById('customerPaidPost').value = paid;\n");
      out.write("    \n");
      out.write("    var vRow = document.getElementById('voucherSummaryRow');\n");
      out.write("    if (vRow) vRow.style.display = voucherDisc > 0 ? 'flex' : 'none';\n");
      out.write("    var vText = document.getElementById('voucherAmountText');\n");
      out.write("    if (vText) vText.textContent = '- ' + money(voucherDisc);\n");
      out.write("    if (currentPayMethod === 'bank') updateQR(grand);\n");
      out.write("}\n");
      out.write("\n");
