      out.write("\n");
      out.write("function selectBank(el, code, name) {\n");
      out.write("    selectedBank = code;\n");
      out.write("    document.querySelectorAll('.qr-bank-btn').forEach(function(b){b.classList.remove('active')});\n");
      out.write("    el.classList.add('active');\n");
      out.write("    var info = bankInfo[code];\n");
      out.write("    document.getElementById('bankGuide').innerHTML = info ? info.guide : '';\n");
      out.write("    var subtotal = cart.reduce(function(t,i){return t+i.gia*i.qty},0);\n");
      out.write("    var disc = Math.round(subtotal * currentDiscountPct / 100);\n");
      out.write("    var afterDisc = subtotal - disc;\n");
      out.write("    var vat = Math.round(subtotal * VAT_PCT / 100);\n");
      out.write("    var grand = afterDisc + vat;\n");
      out.write("    updateQR(grand);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function updateQR(amount) {\n");
      out.write("    if (typeof stopQRPolling === 'function') stopQRPolling();\n");
      out.write("    if (!amount || amount <= 0 || !cart.length) {\n");
      out.write("        document.getElementById('qrCodeImg').style.display='none';\n");
      out.write("        document.getElementById('qrPlaceholder').style.display='block';\n");
      out.write("        document.getElementById('qrPlaceholder').innerHTML = \"Vui lòng chọn sản phẩm vào đơn để tạo mã QR.\";\n");
      out.write("        var stEl = document.getElementById('qrStatusText');\n");
      out.write("        if (stEl) stEl.textContent = \"Chờ thêm sản phẩm...\";\n");
      out.write("        return;\n");
      out.write("    }\n");
      out.write("    var info = bankInfo[selectedBank];\n");
      out.write("    if (!info) return;\n");
      out.write("    \n");
      out.write("    document.getElementById('qrCodeImg').style.display='none';\n");
      out.write("    document.getElementById('qrPlaceholder').style.display='block';\n");
      out.write("    document.getElementById('qrPlaceholder').innerHTML = \"Đang tạo mã QR xác nhận...\";\n");
      out.write("    var stEl = document.getElementById('qrStatusText');\n");
      out.write("    if (stEl) stEl.textContent = \"Chờ khách quét QR & xác nhận trên điện thoại...\";\n");
      out.write("\n");
      out.write("    var custName = typeof selectedCustomer !== 'undefined' && selectedCustomer ? (selectedCustomer.hoTen || \"Khách hàng\") : \"Khách vãng lai\";\n");
      out.write("    var bankName = info.name || selectedBank;\n");
      out.write("    \n");
      out.write("    fetch(\"");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${pageContext.request.contextPath}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null, false));
      out.write("/QRConfirmServlet?action=init&amount=\" + amount + \"&bank=\" + encodeURIComponent(bankName) + \"&customer=\" + encodeURIComponent(custName))\n");
      out.write("        .then(function(r) { return r.json(); })\n");
      out.write("        .then(function(data) {\n");
      out.write("            if (data && data.token && data.url) {\n");
      out.write("                var img = document.getElementById('qrCodeImg');\n");
      out.write("                img.onload = function(){ document.getElementById('qrPlaceholder').style.display='none'; img.style.display='block'; };\n");
      out.write("                img.onerror = function(){ document.getElementById('qrPlaceholder').innerHTML='Lỗi hiển thị ảnh QR.'; };\n");
      out.write("                img.src = \"https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=\" + encodeURIComponent(data.url);\n");
      out.write("                \n");
      out.write("                var guideHtml = info.guide;\n");
      out.write("                if (data.lanIP) {\n");
      out.write("                    guideHtml += '<br><span style=\"color:var(--color-success);font-weight:700\">Mạng nội bộ IP: ' + data.lanIP + '</span>';\n");
      out.write("                }\n");
      out.write("                document.getElementById('bankGuide').innerHTML = guideHtml;\n");
      out.write("                \n");
      out.write("                if (typeof startQRPolling === 'function') startQRPolling(data.token);\n");
      out.write("            }\n");
      out.write("        })\n");
      out.write("        .catch(function(e) {\n");
      out.write("            console.log(\"Lỗi tạo QR:\", e);\n");
      out.write("        });\n");
      out.write("}\n");
      out.write("\n");
      out.write("function submitInvoice(type) {\n");
      out.write("    calculateTotals();\n");
      out.write("    if (!cart.length) { alert('Giỏ hàng trống. Vui lòng chọn sản phẩm.'); return; }\n");
      out.write("\n");
      out.write("    var subtotal = cart.reduce(function(t,i){return t+i.gia*i.qty},0);\n");
      out.write("    var disc = Math.round(subtotal * currentDiscountPct / 100);\n");
      out.write("    var voucherDisc = appliedVoucherAmount > 0 ? Math.min(appliedVoucherAmount, subtotal - disc) : 0;\n");
      out.write("    var afterDisc = subtotal - disc - voucherDisc;\n");
      out.write("    var vat = Math.round(subtotal * VAT_PCT / 100);\n");
      out.write("    var grand = afterDisc + vat;\n");
      out.write("\n");
      out.write("    if (type === 'paid' && currentPayMethod === 'cash') {\n");
      out.write("        var paidStr = (document.getElementById('customerPaidInput').value || '').replace(/[^0-9]/g, '');\n");
      out.write("        var paid = parseFloat(paidStr) || 0;\n");
      out.write("        if (paid < grand) { alert('Số tiền khách đưa (' + money(paid) + ') chưa đủ để thanh toán (' + money(grand) + ')!'); return; }\n");
      out.write("        document.getElementById('orderNotePost').value = 'Bán hàng tại quầy';\n");
      out.write("    } else if (type === 'paid' && currentPayMethod === 'bank') {\n");
      out.write("        alert('Vui lòng yêu cầu khách hàng quét mã QR trên màn hình và xác nhận trên điện thoại.\\n\\nHệ thống sẽ tự động hoàn tất hóa đơn sau khi khách xác nhận.');\n");
      out.write("        return;\n");
      out.write("    } else {\n");
      out.write("        var paidHoldStr = (document.getElementById('customerPaidInput').value || '').replace(/[^0-9]/g, '');\n");
      out.write("        var paidHold = parseFloat(paidHoldStr) || 0;\n");
      out.write("        if (paidHold > 0) {\n");
      out.write("            alert('Khi tạo hóa đơn chờ thì không được nhận tiền ở phần \"Khách đưa\" vì đơn chưa thanh toán!');\n");
      out.write("            return;\n");
      out.write("        }\n");
      out.write("        if (appliedVoucherCode && appliedVoucherCode.trim() !== '') {\n");
      out.write("            alert('Không thể áp dụng voucher vào các đơn hàng tạm giữ!');\n");
      out.write("            cancelVoucher();\n");
      out.write("            return;\n");
      out.write("        }\n");
      out.write("        document.getElementById('customerPaidPost').value = 0;\n");
      out.write("        document.getElementById('orderNotePost').value = 'Hóa đơn chờ - Bán hàng tại quầy';\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    document.getElementById('voucherCodePost').value = appliedVoucherCode || '';\n");
